import sys

def next_id(last_id):
    """Given an id like 'ORD-243G', return the next id in base-36 sequence."""
    prefix, suffix = last_id[:4], last_id[4:]
    # Convert base-36 suffix to integer, increment, convert back
    val = int(suffix, 36) + 1
    # Re-encode as 4-char base-36 uppercase
    chars = []
    for _ in range(4):
        rem = val % 36
        if rem < 10:
            chars.append(chr(ord('0') + rem))
        else:
            chars.append(chr(ord('A') + rem - 10))
        val //= 36
    return prefix + ''.join(reversed(chars))

def main():
    with open('ids.txt') as f:
        lines = [line.strip() for line in f if line.strip()]
    if not lines:
        print('ORD-0000')
        return
    last = lines[-1]
    print(next_id(last))

if __name__ == '__main__':
    main()

