import sys

DIGITS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def to_base36(n: int, width: int = 4) -> str:
    """Convert an integer to a zero-padded base36 string."""
    if n == 0:
        return DIGITS[0] * width
    chars = []
    while n > 0:
        chars.append(DIGITS[n % 36])
        n //= 36
    return "".join(reversed(chars)).rjust(width, "0")


def next_id(ids_path: str = "ids.txt") -> str:
    with open(ids_path) as f:
        lines = [line.strip() for line in f if line.strip()]

    if not lines:
        return "ORD-" + to_base36(0)

    last_line = lines[-1]
    prefix = "ORD-"
    suffix = last_line[len(prefix):]

    n = int(suffix, 36)
    n += 1
    return prefix + to_base36(n)


if __name__ == "__main__":
    print(next_id())

