    """Convert a non-negative integer to a base36 string."""
    if n == 0:
        return "0"
    result = []
    while n > 0:
        result.append(DIGITS[n % 36])
        n //= 36
    return "".join(reversed(result))


def from_base36(s: str) -> int:
    """Convert a base36 string to an integer."""
    return int(s, 36)


def main() -> None:
    with open("ids.txt", "r") as f:
        lines = f.read().splitlines()

    last_id = None
    for line in lines:
        m = re.match(r"^ORD-([0-9A-Za-z]{4})$", line.strip())
        if m:
            last_id = m.group(1).upper()

    if last_id is None:
        raise ValueError("No valid order ID found in ids.txt")

    next_num = from_base36(last_id) + 1
    next_suffix = to_base36(next_num).zfill(4).upper()
    print(f"ORD-{next_suffix}")


if __name__ == "__main__":
    main()
