import sys


def main() -> None:
    names: list[str] = []

    with open("attendees.txt", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            # Lines are tab-separated: number \t name
            parts = line.split("\t")
            if len(parts) >= 2:
                name = parts[1].strip()
            else:
                name = parts[0].strip()
            if name:
                names.append(name)

    names.sort()

    with open("roster.txt", "w", encoding="utf-8") as f:
        for name in names:
            f.write(name + "\n")


if __name__ == "__main__":
    main()

