#!/usr/bin/env python3
"""Read events.jsonl, remove duplicate event_ids, write deduped.jsonl."""

import json

def main() -> None:
    seen: set[str] = set()
    deduped: list[str] = []

    with open("events.jsonl") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            event = json.loads(line)
            eid = event.get("event_id")
            if eid is not None and eid in seen:
                continue
            if eid is not None:
                seen.add(eid)
            deduped.append(line)

    with open("deduped.jsonl", "w") as f:
        for line in deduped:
            f.write(line + "\n")

    print(f"Wrote {len(deduped)} events to deduped.jsonl")

if __name__ == "__main__":
    main()

