"""Generate manifest.json: SHA-256 digests for every file under release/."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path("release")
MANIFEST_PATH = Path("manifest.json")


def sha256_digest(filepath: Path) -> str:
    """Return the hex SHA-256 digest of *filepath*."""
    h = hashlib.sha256()
    with open(filepath, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def build_manifest() -> dict[str, str]:
    """Walk release/, collect every regular file, map to its digest."""
    manifest: dict[str, str] = {}
    root = RELEASE_DIR.resolve()

    for path in root.rglob("*"):
        if path.is_file():
            rel = path.relative_to(root.parent)  # relative to repo root
            manifest[str(rel.as_posix())] = sha256_digest(path)

    return manifest


def main() -> None:
    manifest = build_manifest()
    MANIFEST_PATH.write_text(
        json.dumps(manifest, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    print(f"manifest.json written with {len(manifest)} entries")


if __name__ == "__main__":
    main()

