import hashlib
import json
import os

RELEASE_DIR = "release"


def sha256_digest(filepath):
    """Return the SHA-256 hex digest of the file at filepath."""
    h = hashlib.sha256()
    with open(filepath, "rb") as f:
        for chunk in iter(lambda: f.read(8192), b""):
            h.update(chunk)
    return h.hexdigest()


def main():
    manifest = {}
    for dirpath, _, filenames in os.walk(RELEASE_DIR):
        for filename in filenames:
            full_path = os.path.join(dirpath, filename)
            rel_path = os.path.relpath(full_path, RELEASE_DIR)
            manifest[rel_path] = sha256_digest(full_path)

    with open("manifest.json", "w") as f:
        json.dump(manifest, f, indent=2)
        f.write("\n")


if __name__ == "__main__":
    main()
