#!/usr/bin/env python3
"""Generate manifest.json with SHA-256 digests for all files under release/."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path("release")
MANIFEST_FILE = Path("manifest.json")


def sha256_hex(path: Path) -> str:
    """Return the SHA-256 hex digest of *path*."""
    h = hashlib.sha256()
    with open(path, "rb") as f:
        while True:
            chunk = f.read(8192)
            if not chunk:
                break
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    if not RELEASE_DIR.is_dir():
        print(f"Error: {RELEASE_DIR} is not a directory or does not exist.")
        raise SystemExit(1)

    manifest = {}
    for path in sorted(RELEASE_DIR.rglob("*")):
        if path.is_file():
            # Store relative path with forward slashes
            rel = str(path.relative_to(RELEASE_DIR.parent).as_posix())
            manifest[rel] = sha256_hex(path)

    with open(MANIFEST_FILE, "w") as f:
        json.dump(manifest, f, indent=2)

    print(f"Wrote {MANIFEST_FILE} with {len(manifest)} entries.")


if __name__ == "__main__":
    main()

