"""Generate a manifest.json with SHA-256 digests for all files under release/."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path("release")
MANIFEST_PATH = Path("manifest.json")


def sha256_digest(file_path: Path) -> str:
    """Return the SHA-256 hex digest of the given file."""
    h = hashlib.sha256()
    with open(file_path, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    if not RELEASE_DIR.is_dir():
        print(f"error: {RELEASE_DIR} not found")
        return

    manifest: dict[str, str] = {}

    for path in sorted(RELEASE_DIR.rglob("*")):
        if path.is_file():
            digest = sha256_digest(path)
            # Use forward-slash path relative to repo root (e.g. "release/app/main.py")
            manifest[str(path.as_posix())] = digest

    MANIFEST_PATH.write_text(json.dumps(manifest, indent=2) + "\n", encoding="utf-8")
    print(f"wrote {MANIFEST_PATH} with {len(manifest)} entries")


if __name__ == "__main__":
    main()

