"""Read every .txt file under docs/, count word occurrences, write counts.txt."""

import glob
import os
import re

PUNCTUATION = '.,;:!?'


def words_from_file(filepath: str):
    """Yield lowercased words stripped of edge punctuation from a text file."""
    with open(filepath, encoding='utf-8') as f:
        for line in f:
            # Split on whitespace
            for raw in line.split():
                word = raw.lower()
                # Strip punctuation from left edge
                word = word.lstrip(PUNCTUATION)
                # Strip punctuation from right edge
                word = word.rstrip(PUNCTUATION)
                if word:
                    yield word


def main():
    counts = {}

    # Find all .txt files under docs/ recursively
    pattern = os.path.join('docs', '**', '*.txt')
    for filepath in glob.glob(pattern, recursive=True):
        for word in words_from_file(filepath):
            counts[word] = counts.get(word, 0) + 1

    # Write counts.txt sorted alphabetically by word
    with open('counts.txt', 'w', encoding='utf-8') as out:
        for word in sorted(counts):
            out.write(f'{word} {counts[word]}\n')

    print('counts.txt written successfully.')


if __name__ == '__main__':
    main()

