#!/usr/bin/env python3
"""Count word occurrences in all .txt files under docs/."""

import os
import re
from collections import Counter

PUNCTUATION = set(".,;:!?")

def strip_punctuation(word):
    """Strip punctuation characters from word edges."""
    return word.strip(".,;:!?")

def main():
    counter = Counter()
    docs_dir = "docs"

    for root, dirs, files in os.walk(docs_dir):
        for filename in files:
            if filename.endswith(".txt"):
                filepath = os.path.join(root, filename)
                with open(filepath, encoding="utf-8") as f:
                    for line in f:
                        for raw_word in line.split():
                            word = strip_punctuation(raw_word).lower()
                            if word:  # skip empty strings
                                counter[word] += 1

    # Write sorted output
    with open("counts.txt", "w", encoding="utf-8") as out:
        for word in sorted(counter):
            out.write(f"{word} {counter[word]}\n")

if __name__ == "__main__":
    main()

