#!/usr/bin/env python3
"""Count word occurrences in all .txt files under docs/."""

import os
import re
from collections import Counter

PUNCTUATION = '.,;:!?'
ROOT = os.path.dirname(os.path.abspath(__file__))
DOCS_DIR = os.path.join(ROOT, 'docs')
COUNTS_FILE = os.path.join(ROOT, 'counts.txt')


def strip_word_edges(word: str) -> str:
    """Strip punctuation characters from the edges of a word."""
    return word.strip(PUNCTUATION)


def main():
    counter = Counter()

    if not os.path.isdir(DOCS_DIR):
        print(f"Error: {DOCS_DIR} does not exist")
        return

    for entry in sorted(os.listdir(DOCS_DIR)):
        if not entry.endswith('.txt'):
            continue
        path = os.path.join(DOCS_DIR, entry)
        if not os.path.isfile(path):
            continue
        with open(path, encoding='utf-8') as f:
            for line in f:
                for raw_word in line.split():
                    word = raw_word.lower()
                    word = strip_word_edges(word)
                    if word:  # skip empty strings
                        counter[word] += 1

    with open(COUNTS_FILE, 'w', encoding='utf-8') as f:
        for word in sorted(counter):
            f.write(f'{word} {counter[word]}\n')

    print(f'Wrote {COUNTS_FILE} with {len(counter)} unique words')


if __name__ == '__main__':
    main()

